#include <stdio.h>

int main() {
    int N;
    if (scanf("%d", &N) != 1) return 0;

    if (N == 2) {
        printf("-1\n");
        return 0;
    }

    if (N == 1) {
        printf("1\n");
        return 0;
    }

    int S[40];

    if (N % 2 == 1) {
        for (int i = 0; i < N; i++) {
            S[i] = i + 1;
        }
    } else {
        int m = N / 2;
        for (int i = 0; i < N - 1; i++) {
            S[i] = i + 1;
        }
        S[N - 1] = 3 * m;
    }

    int maxB = S[N - 1];
    int M = maxB + 1;

    for (int i = 0; i < N; i++) {
        for (int j = 0; j < N; j++) {
            if (j > 0) printf(" ");
            printf("%d", M * S[i] + S[j]);
        }
        printf("\n");
    }

    return 0;
}
